import{_ as i,o as a,c as e,ak as d}from"./chunks/framework.DvrM7GBU.js";const _=JSON.parse('{"title":"文档状态分级规则","description":"","frontmatter":{},"headers":[],"relativePath":"维护与报告/文档状态分级规则.md","filePath":"维护与报告/文档状态分级规则.md","lastUpdated":1777893104000}'),r={name:"维护与报告/文档状态分级规则.md"};function o(c,l,h,t,n,s){return a(),e("div",null,[...l[0]||(l[0]=[d('<h1 id="文档状态分级规则" tabindex="-1">文档状态分级规则 <a class="header-anchor" href="#文档状态分级规则" aria-label="Permalink to “文档状态分级规则”">​</a></h1><p>一句话摘要：这是一份面向整个资料库的文档成熟度说明，用来统一判断一篇文档当前是草稿、整理中、已整理，还是可作为高稳定入口使用。</p><ul><li>适合对象：维护者、研究者、AI 检索系统</li><li>当前状态：已整理</li><li>可信度：<code>[已确认]</code></li><li>关联文档：<code>docs/维护与报告/资料规范与状态总览.md</code>、<code>docs/维护与报告/维护流程说明.md</code>、<code>docs/元信息/知识库文档状态总表.md</code></li></ul><h2 id="为什么需要状态分级" tabindex="-1">为什么需要状态分级 <a class="header-anchor" href="#为什么需要状态分级" aria-label="Permalink to “为什么需要状态分级”">​</a></h2><p>如果没有统一分级：</p><ul><li>读者不知道一篇文档能不能直接信</li><li>AI 不知道该把哪类文档当高权重入口</li><li>维护者也不知道应该先补哪一层</li></ul><p>所以资料库里的文档，最好至少明确“成熟度”和“可信度”两件事。</p><h2 id="推荐状态分级" tabindex="-1">推荐状态分级 <a class="header-anchor" href="#推荐状态分级" aria-label="Permalink to “推荐状态分级”">​</a></h2><h3 id="_1-草稿" tabindex="-1">1. 草稿 <a class="header-anchor" href="#_1-草稿" aria-label="Permalink to “1. 草稿”">​</a></h3><p>适用情况：</p><ul><li>只有零散记录</li><li>结构不完整</li><li>标题与正文还没统一</li><li>基本没有回链或关联阅读</li></ul><p>建议处理：</p><ul><li>先补标题与摘要</li><li>再补最小结构</li><li>暂时不要当稳定入口页</li></ul><h3 id="_2-整理中" tabindex="-1">2. 整理中 <a class="header-anchor" href="#_2-整理中" aria-label="Permalink to “2. 整理中”">​</a></h3><p>适用情况：</p><ul><li>已有较明确主题</li><li>已开始分段与分类</li><li>但仍缺少证据、回链或统一头部</li></ul><p>建议处理：</p><ul><li>补一句话摘要</li><li>补适合对象 / 当前状态 / 可信度</li><li>补栏目入口与关联阅读</li></ul><h3 id="_3-已整理" tabindex="-1">3. 已整理 <a class="header-anchor" href="#_3-已整理" aria-label="Permalink to “3. 已整理”">​</a></h3><p>适用情况：</p><ul><li>结构完整</li><li>阅读路径清楚</li><li>已接入栏目页或总导航</li><li>有较明确的结论与说明</li></ul><p>建议处理：</p><ul><li>可作为稳定阅读入口</li><li>后续继续补 OCR 证据和双向链接</li></ul><h3 id="_4-核心入口" tabindex="-1">4. 核心入口 <a class="header-anchor" href="#_4-核心入口" aria-label="Permalink to “4. 核心入口”">​</a></h3><p>适用情况：</p><ul><li>能承担栏目页或专题总入口作用</li><li>与多个高价值专题有稳定连接</li><li>对玩家和 AI 都有较高检索价值</li></ul><p>建议处理：</p><ul><li>保持结构稳定</li><li>每次扩写都要检查全局回链</li><li>尽量避免频繁大改路径或命名</li></ul><h2 id="可信度标记建议" tabindex="-1">可信度标记建议 <a class="header-anchor" href="#可信度标记建议" aria-label="Permalink to “可信度标记建议”">​</a></h2><p>除了状态，还建议统一写明可信度：</p><ul><li><code>[已确认]</code>：有明确来源、已有较高把握</li><li><code>[高可信推断]</code>：虽未完全实锤，但已有较强上下文支持</li><li><code>[待验证]</code>：目前还不能直接下结论，需要继续查证</li></ul><h2 id="最小合格标准" tabindex="-1">最小合格标准 <a class="header-anchor" href="#最小合格标准" aria-label="Permalink to “最小合格标准”">​</a></h2><p>一篇文档如果想达到“已整理”，建议至少满足：</p><ul><li>有清晰标题</li><li>有一句话摘要</li><li>有适合对象</li><li>有当前状态</li><li>有可信度</li><li>有关联阅读</li><li>能从栏目页或总导航进入</li></ul><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to “关联阅读”">​</a></h2><ul><li><code>docs/维护与报告/维护与报告导航.md</code></li><li><code>docs/维护与报告/维护流程说明.md</code></li><li><code>docs/元信息/知识库文档状态总表.md</code></li></ul>',36)])])}const u=i(r,[["render",o]]);export{_ as __pageData,u as default};
